package net.officefloor.hq.app.invoice;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.project.Project;

/** An invoice raised against a project. */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "project_id", nullable = false)
    private Project project;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 16)
    private InvoiceStatus status = InvoiceStatus.DRAFT;

    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    protected Invoice() {
    }

    public Invoice(Project project, BigDecimal amount, LocalDate issuedDate, LocalDate dueDate) {
        this.project = project;
        this.amount = amount;
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
    }

    public Long getId() {
        return id;
    }

    public Project getProject() {
        return project;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public InvoiceStatus getStatus() {
        return status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    /** Marks this invoice as sent to the client. */
    public void markSent() {
        this.status = InvoiceStatus.SENT;
    }

    /** Marks this invoice as paid. */
    public void markPaid() {
        this.status = InvoiceStatus.PAID;
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    List<Invoice> findByProjectIdOrderById(Long projectId);

    /** All invoices across every project, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project ORDER BY i.id")
    List<Invoice> findAllWithProject();

    /** Invoices across every project at the given status, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project WHERE i.status = :status ORDER BY i.id")
    List<Invoice> findAllWithProjectByStatus(InvoiceStatus status);

    /** Sum of the amounts of all invoices with the given status (zero when there are none). */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status = :status")
    BigDecimal sumAmountByStatus(InvoiceStatus status);
}
package net.officefloor.hq.app.invoice;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Payload to add an invoice to a project. The dates are optional: the issue date defaults to today
 * and the due date to {@link #DEFAULT_TERM_DAYS} days after the issue date.
 */
public record InvoiceRequest(
        @NotNull @DecimalMin("0.01") @Digits(integer = 10, fraction = 2) BigDecimal amount,
        LocalDate issuedDate,
        LocalDate dueDate) {

    /** Days between issue and due date when no due date is given. */
    public static final int DEFAULT_TERM_DAYS = 30;
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;

public record InvoiceResponse(Long id, Long projectId, BigDecimal amount, InvoiceStatus status,
        LocalDate issuedDate, LocalDate dueDate) {

    static InvoiceResponse from(Invoice invoice) {
        return new InvoiceResponse(invoice.getId(), invoice.getProject().getId(), invoice.getAmount(),
                invoice.getStatus(), invoice.getIssuedDate(), invoice.getDueDate());
    }
}
package net.officefloor.hq.app.invoice;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.project.Project;
import net.officefloor.hq.app.project.ProjectRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final ProjectRepository projects;
    private final Audit audit;

    public InvoiceService(InvoiceRepository invoices, ProjectRepository projects, Audit audit) {
        this.invoices = invoices;
        this.projects = projects;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<InvoiceResponse> listForProject(Long projectId) {
        if (!projects.existsById(projectId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project");
        }
        return invoices.findByProjectIdOrderById(projectId).stream().map(InvoiceResponse::from).toList();
    }

    /**
     * Every invoice across all projects, with the name of the project each one is for, narrowed to
     * the given status when one is supplied.
     */
    @Transactional(readOnly = true)
    public List<InvoiceSummaryResponse> listAll(InvoiceStatus status) {
        List<Invoice> found =
                status == null ? invoices.findAllWithProject() : invoices.findAllWithProjectByStatus(status);
        return found.stream().map(InvoiceSummaryResponse::from).toList();
    }

    @Transactional
    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
        Project project = projects.findById(projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
        LocalDate due = request.dueDate() != null ? request.dueDate() : issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS);
        if (due.isBefore(issued)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
        }
        Invoice saved = invoices.save(new Invoice(project, request.amount(), issued, due));
        return InvoiceResponse.from(saved);
    }

    /** Sends a draft invoice and records the sending in the audit log. */
    @Transactional
    public InvoiceResponse send(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
        }
        invoice.markSent();
        invoices.flush();
        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return InvoiceResponse.from(invoice);
    }

    /** Marks a sent invoice paid and records the payment in the audit log. */
    @Transactional
    public InvoiceResponse pay(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.SENT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a sent invoice can be paid");
        }
        invoice.markPaid();
        invoices.flush();
        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return InvoiceResponse.from(invoice);
    }

    private Invoice find(Long projectId, Long invoiceId) {
        return invoices.findById(invoiceId)
                .filter(i -> i.getProject().getId().equals(projectId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
    }
}
package net.officefloor.hq.app.invoice;

/** Lifecycle stage of an invoice: DRAFT -> SENT -> PAID. */
public enum InvoiceStatus {
    DRAFT,
    SENT,
    PAID
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;

/** An invoice as listed across all projects: carries the name of the project it is for. */
public record InvoiceSummaryResponse(Long id, Long projectId, String projectName, BigDecimal amount,
        InvoiceStatus status, LocalDate issuedDate, LocalDate dueDate) {

    static InvoiceSummaryResponse from(Invoice invoice) {
        return new InvoiceSummaryResponse(invoice.getId(), invoice.getProject().getId(),
                invoice.getProject().getName(), invoice.getAmount(), invoice.getStatus(),
                invoice.getIssuedDate(), invoice.getDueDate());
    }
}
CREATE TABLE invoice (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    CONSTRAINT invoice_project_fk FOREIGN KEY (project_id) REFERENCES project (id),
    CONSTRAINT invoice_amount_positive CHECK (amount > 0)
);

